import { Component, OnInit, OnDestroy, ChangeDetectorRef } from '@angular/core';
import { Router, NavigationEnd } from '@angular/router';
import { filter } from 'rxjs/operators';

@Component({
  selector: 'app-navbar',
  templateUrl: './navbar.component.html',
  styleUrls: ['./navbar.component.css'],
})
export class NavbarComponent implements OnInit, OnDestroy {
  isLoggedIn = false;
  username = '';
  cartCount = 0;
  private storageListener: any;
  private routerSubscription: any;

  constructor(
    private router: Router,
    private cdr: ChangeDetectorRef,
  ) {}

  ngOnInit(): void {
    this.checkLoginStatus();
    this.loadCartCount();

    // Listen for route changes to update login status
    this.routerSubscription = this.router.events
      .pipe(filter((event) => event instanceof NavigationEnd))
      .subscribe(() => {
        this.checkLoginStatus();
        this.cdr.detectChanges();
      });

    // Listen for storage changes (for logout from other tabs)
    this.storageListener = (event: StorageEvent) => {
      if (
        event.key === 'logout' ||
        event.key === 'username' ||
        event.key === 'token'
      ) {
        this.checkLoginStatus();
        this.loadCartCount();
        this.cdr.detectChanges();
      }
    };
    window.addEventListener('storage', this.storageListener);
  }

  ngOnDestroy(): void {
    if (this.storageListener) {
      window.removeEventListener('storage', this.storageListener);
    }
    if (this.routerSubscription) {
      this.routerSubscription.unsubscribe();
    }
  }

  checkLoginStatus(): void {
    // Check multiple storage keys for login status
    const user = localStorage.getItem('username');
    const token = localStorage.getItem('token');
    const email = localStorage.getItem('email');

    // User is logged in if username exists AND token exists
    this.isLoggedIn = !!(
      user &&
      user !== 'null' &&
      user !== 'undefined' &&
      user !== '' &&
      token
    );
    this.username = user || '';

    console.log('Login Status Check:', {
      isLoggedIn: this.isLoggedIn,
      username: this.username,
      hasToken: !!token,
    });
  }

  loadCartCount(): void {
    try {
      const cart = JSON.parse(localStorage.getItem('cart') || '[]');
      this.cartCount = cart.length;
    } catch (e) {
      this.cartCount = 0;
    }
  }

  getUserInitial(): string {
    return this.username ? this.username.charAt(0).toUpperCase() : 'U';
  }

  logout(): void {
    if (confirm('Are you sure you want to logout?')) {
      // Clear all user data from localStorage
      localStorage.removeItem('username');
      localStorage.removeItem('email');
      localStorage.removeItem('token');
      localStorage.removeItem('role');
      localStorage.removeItem('userId');
      localStorage.removeItem('cart');

      // Set logout flag for other tabs
      localStorage.setItem('logout', Date.now().toString());

      // Reset state
      this.isLoggedIn = false;
      this.username = '';
      this.cartCount = 0;

      // Force change detection
      this.cdr.detectChanges();

      // Show success message
      alert('Logged out successfully! 👋');

      // Navigate to home page
      this.router.navigate(['/home']);
    }
  }
}
<mat-toolbar color="primary" class="navbar">
  <div class="logo-container">
    <span class="logo-icon">🛒</span>
    <span class="logo">Ecommerce Online Marketplace</span>
  </div>

  <span class="spacer"></span>

  <div class="nav-links">
    <a mat-button routerLink="/home" routerLinkActive="active-link">
      <mat-icon>home</mat-icon>
      Home
    </a>

    <a mat-button routerLink="/about" routerLinkActive="active-link">
      <mat-icon>info</mat-icon>
      About
    </a>

    <a mat-button routerLink="/contact" routerLinkActive="active-link">
      <mat-icon>contact_mail</mat-icon>
      Contact
    </a>

    <!-- Show these when NOT logged in -->
    <ng-container *ngIf="!isLoggedIn">
      <a mat-button routerLink="/login" routerLinkActive="active-link">
        <mat-icon>login</mat-icon>
        Login
      </a>

      <a
        mat-button
        routerLink="/register"
        routerLinkActive="active-link"
        class="register-btn"
      >
        <mat-icon>person_add</mat-icon>
        Register
      </a>
    </ng-container>

    <!-- Show these when logged in -->
    <ng-container *ngIf="isLoggedIn">
      <a mat-button routerLink="/user/items" routerLinkActive="active-link">
        <mat-icon>store</mat-icon>
        Shop
      </a>

      <button mat-button [matMenuTriggerFor]="userMenu" class="user-menu-btn">
        <mat-icon>account_circle</mat-icon>
        {{ username }}
        <mat-icon>arrow_drop_down</mat-icon>
      </button>

      <mat-menu #userMenu="matMenu">
        <button mat-menu-item routerLink="/profile">
          <mat-icon>account_box</mat-icon>
          My Profile
        </button>
        <button mat-menu-item routerLink="/orders">
          <mat-icon>shopping_bag</mat-icon>
          My Orders
        </button>
        <button mat-menu-item routerLink="/cart">
          <mat-icon>shopping_cart</mat-icon>
          Cart
          <span class="cart-count" *ngIf="cartCount > 0">{{ cartCount }}</span>
        </button>
        <button mat-menu-item routerLink="/wishlist">
          <mat-icon>favorite</mat-icon>
          Wishlist
        </button>
        <mat-divider></mat-divider>
        <button mat-menu-item (click)="logout()" class="logout-item">
          <mat-icon>exit_to_app</mat-icon>
          Logout
        </button>
      </mat-menu>
    </ng-container>
  </div>
</mat-toolbar>
